schema:
CREATE TABLE t1 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1)
);

CREATE TABLE t2 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1)
);

CREATE TABLE t3 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1)
);

CREATE TABLE t4 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    c3 SMALLINT NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t3(c1),
    FOREIGN KEY (c2) REFERENCES t1(c1)
);

CREATE TABLE t5 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    c3 DECIMAL(5,2) NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t1(c1),
    FOREIGN KEY (c2) REFERENCES t2(c1)
);

CREATE TABLE t6 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t3(c1),
    FOREIGN KEY (c2) REFERENCES t2(c1)
);

counterexample:
INSERT INTO t1 (c1) VALUES ('A');
INSERT INTO t1 (c1) VALUES ('B');
INSERT INTO t1 (c1) VALUES ('C');

INSERT INTO t2 (c1, c2) VALUES ('Amstel', 'Beer');
INSERT INTO t2 (c1, c2) VALUES ('Corona', 'Beer');

-- This row will be selected by Q2 (because c2 = 'Amstel') even though c3 is not > 2
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'Amstel', 1);

-- This row will be rejected by both queries because c2 = 'Corona' but c3 is not > 2
INSERT INTO t5 (c1, c2, c3) VALUES ('B', 'Corona', 1);

-- This row is accepted by both queries because it meets (c2 = 'Corona' and c3 > 2)
INSERT INTO t5 (c1, c2, c3) VALUES ('C', 'Corona', 3);

