counterexample:
INSERT INTO t1 (c1, c2) VALUES ('B1', 'dummy');

INSERT INTO t2 (c1, c2) VALUES ('Amstel', 'dummy');
INSERT INTO t2 (c1, c2) VALUES ('Corona', 'dummy');

INSERT INTO t5 (c1, c2, c3) VALUES ('B1', 'Amstel', 1.00);  -- This row qualifies for Q2 due to c2 = 'Amstel' even though c3 <= 2
