);

CREATE TABLE t5 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    c3 DECIMAL(5,2) NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t1(c1),
    FOREIGN KEY (c2) REFERENCES t2(c1)
);

CREATE TABLE t6 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t3(c1),
    FOREIGN KEY (c2) REFERENCES t2(c1)
);

counterexample:
INSERT INTO t1 (c1, c2) VALUES ('A', 't1_A');
INSERT INTO t1 (c1, c2) VALUES ('B', 't1_B');

INSERT INTO t2 (c1, c2) VALUES ('Amstel', 'dummy');
INSERT INTO t2 (c1, c2) VALUES ('Corona', 'dummy');
INSERT INTO t2 (c1, c2) VALUES ('NonCorona', 'dummy');

INSERT INTO t3 (c1, c2) VALUES ('B', 't3_B');

-- t5: Q1 uses t5; only the row with c1 = 'A' qualifies because c3 > 2 and c2 = 'Corona'
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'Corona', 3.00);
-- This row does not qualify for Q1 (c3 <= 2) and is used only to affect subquery of Q2
INSERT INTO t5 (c1, c2, c3) VALUES ('B', 'Amstel', 1.00);

-- t6: Provide a row for c1 = 'B' with c2 different from 'Corona' so that 'B' appears in Q2's subquery
INSERT INTO t6 (c1, c2) VALUES ('B', 'NonCorona');

-- t4: Q2 runs on t4; using c1 = 'B' and c2 = 'A'. The condition that t4.c2 is in (SELECT c1 FROM t5 WHERE c2 = 'Corona') is met because 'A' appears from t5 and the condition on t6 is met for 'B'
INSERT INTO t4 (c1, c2, c3) VALUES ('B', 'A', 10);

