counterexample:
-- Insert supporting rows for foreign key constraints
-- t1: c1 is PK; both candidate values and 'Corona' (used as t4.c2) must exist
INSERT INTO t1 (c1, c2) VALUES ('A', 'dummyA');
INSERT INTO t1 (c1, c2) VALUES ('B', 'dummyB');
INSERT INTO t1 (c1, c2) VALUES ('Corona', 'dummyCorona');

-- t2: c1 is PK; 'Corona' (used as t5.c2 and t6.c2) must exist
INSERT INTO t2 (c1, c2) VALUES ('Corona', 'dummy');

-- t3: c1 is PK; candidate values for t4 and t6 must exist
INSERT INTO t3 (c1, c2) VALUES ('A', 'infoA');
INSERT INTO t3 (c1, c2) VALUES ('B', 'infoB');

-- t4: (c1, c2, c3) with foreign keys: c1 references t3 and c2 references t1
INSERT INTO t4 (c1, c2, c3) VALUES ('A', 'Corona', 1);
INSERT INTO t4 (c1, c2, c3) VALUES ('B', 'Corona', 2);

-- t5: (c1, c2, c3) with foreign keys: c1 references t1 and c2 references t2
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'Corona', 10.00);
INSERT INTO t5 (c1, c2, c3) VALUES ('B', 'Corona', 20.00);

-- t6: (c1, c2) with foreign keys: c1 references t3 and c2 references t2
-- Only candidate 'B' appears in t6 with c2 'Corona'
INSERT INTO t6 (c1, c2) VALUES ('B', 'Corona');

schema:
CREATE TABLE t1 (
