-- Insert into t3 (the primary table for Q1)
INSERT INTO t3 (c1, c2) VALUES ('A', 'foo');
INSERT INTO t3 (c1, c2) VALUES ('B', 'bar');

-- Insert into t1 (needed for t4 foreign key)
INSERT INTO t1 (c1, c2) VALUES ('T1_B', 'val1');

-- Insert into t2 (needed for t5 and t6 foreign keys)
INSERT INTO t2 (c1, c2) VALUES ('T2_B', 'val2');

-- Insert into t4. Only row here is for t3 with c1 = 'B'.
INSERT INTO t4 (c1, c2, c3) VALUES ('B', 'T1_B', 1);

-- Insert into t5. This row joins with t4 via t4.c2 = t5.c1 and provides a value for t5.c2
INSERT INTO t5 (c1, c2, c3) VALUES ('T1_B', 'T2_B', 10.00);

-- Insert into t6. This row ensures that for t3 'B', the t5 row's c2 ('T2_B') is present in t6
INSERT INTO t6 (c1, c2) VALUES ('B', 'T2_B');

