INSERT INTO t1 (c1, c2) VALUES ('Reject', 'dummy');

-- Insert necessary rows for t2 (referenced by t5 and t6)
INSERT INTO t2 (c1, c2) VALUES ('T5_B', 'dummy');
INSERT INTO t2 (c1, c2) VALUES ('NoMatch', 'dummy');

-- For t3 = 'B', insert two t4 rows:
-- One row that will be used for the valid chain (for Q2)
INSERT INTO t4 (c1, c2, c3) VALUES ('B', 'T4_B', 1);
-- Another row that will force a violation in Q1
INSERT INTO t4 (c1, c2, c3) VALUES ('B', 'Reject', 1);

-- Insert corresponding rows in t5
-- Row for the valid chain: links the t4 row 'T4_B' with t6
INSERT INTO t5 (c1, c2, c3) VALUES ('T4_B', 'T5_B', 1.00);
-- Row for the violation: joins with the t4 row 'Reject'
INSERT INTO t5 (c1, c2, c3) VALUES ('Reject', 'NoMatch', 1.00);

-- Insert t6 row only for the chain, not for the violation
INSERT INTO t6 (c1, c2) VALUES ('B', 'T5_B');

