-- t3: Two rows, one for each case
INSERT INTO t3 (c1, c2) VALUES ('A', 'valueA');
INSERT INTO t3 (c1, c2) VALUES ('B', 'valueB');

-- For t3 row 'B', create a join in t4 and t5
-- t4: Must reference t3 (c1) and t1 (c2)
INSERT INTO t4 (c1, c2, c3) VALUES ('B', 'X', 1);

-- t5: Must reference t1 (c1) and t2 (c2); here we use 'Corona' for t5.c2 to satisfy Q2's join condition
INSERT INTO t5 (c1, c2, c3) VALUES ('X', 'Corona', 10.00);

-- t6: Do not insert any rows for t3 'A' or 'B' so that:
-- For t3 'A': No join exists, so Q1 returns it, but Q2 fails the join condition.
-- For t3 'B': The t6 subquery is empty (so condition in Q1 becomes true for the join row and then negated by NOT EXISTS, omitting B), while Q2 uses the join to include it (given B is not associated with any t6 row having 'Corona').

