-- Insert data for t1. t1 is used for t5 (as foreign key for c1) and for t4 (t4.c2 must refer to an existing t1 row). We deliberately do NOT insert a row for 'B1'.
INSERT INTO t1 (c1, c2) VALUES ('X1', 'dummy1');
INSERT INTO t1 (c1, c2) VALUES ('X2', 'dummy2');

-- Insert data for t2. t2 is referenced by t5 (c2 column).
INSERT INTO t2 (c1, c2) VALUES ('G1', 'group');

-- Insert data for t3. t3 is referenced by t4 (c1 column). We must insert a row for 'B1' to satisfy the foreign key in t4.
INSERT INTO t3 (c1, c2) VALUES ('B1', 'dummy');

-- Insert data for t4. Note: t4.c2 references t1, so we use 'X1' and 'X2' which already exist in t1. t4.c1 is set to 'B1' (which satisfies LIKE 'B%' and is in t3) but we do not add 'B1' in t1, so Q2's join will fail.
INSERT INTO t4 (c1, c2, c3) VALUES ('B1', 'X1', 0);
INSERT INTO t4 (c1, c2, c3) VALUES ('B1', 'X2', 0);

-- Insert data for t5. t5.c1 references t1 and t5.c2 references t2. Create two rows with group 'G1'.
INSERT INTO t5 (c1, c2, c3) VALUES ('X1', 'G1', 10.00);
INSERT INTO t5 (c1, c2, c3) VALUES ('X2', 'G1', 20.00);

