counterexample:
INSERT INTO t1 (c1, c2) VALUES ('A', 'dummy');

-- t3 is referenced by t4 (c1), so we insert rows with keys 'x' and 'y' corresponding to t4 rows
INSERT INTO t3 (c1, c2) VALUES ('x', 'dummy'), ('y', 'dummy');

-- t2 is referenced by t5 (c2), so we insert a row in t2
INSERT INTO t2 (c1, c2) VALUES ('z', 'dummy');

-- Insert two rows in t4 for t1 'A'.
-- For Q1, the subquery orders by c3 DESC so it picks the row with the highest c3, i.e. row with c1 'x'.
-- For Q2, the subquery orders by c3 ASC so it picks the row with the lowest c3, i.e. row with c1 'y'.
INSERT INTO t4 (c1, c2, c3) VALUES ('x', 'A', 20), ('y', 'A', 10);

-- Insert one row in t5 for t1 'A'.
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'z', 5.00);

