counterexample:
-- Insert records into t1: two bars
INSERT INTO t1 (c1, c2) VALUES ('barA', 'unused');
INSERT INTO t1 (c1, c2) VALUES ('barB', 'unused');

-- Insert records into t2: needed for t5 foreign key. Using bar names as keys.
INSERT INTO t2 (c1, c2) VALUES ('barA', 'unused');
INSERT INTO t2 (c1, c2) VALUES ('barB', 'unused');

-- Insert a record into t3: needed for t4 foreign key
INSERT INTO t3 (c1, c2) VALUES ('drinkerA', 'dummy');

-- Insert a record into t4 only for barA
INSERT INTO t4 (c1, c2, c3) VALUES ('drinkerA', 'barA', 100);

-- Insert records into t5 for both bars
-- For barA, so that t4 join t5 works in Q2
INSERT INTO t5 (c1, c2, c3) VALUES ('barA', 'barA', 10.00);
-- For barB, note: no matching t4 record for barB, so Q2 will not see it
INSERT INTO t5 (c1, c2, c3) VALUES ('barB', 'barB', 20.00);

-- t6 is not used in these queries so no inserts are needed.

