INSERT INTO t3 (c1, c2) VALUES ('d1', 'info_d1');
INSERT INTO t3 (c1, c2) VALUES ('d2', 'info_d2');

-- Insert data into t4 (drink records linking drinkers to bars)
-- Only bar2 gets t4 records; creating two records to test ordering (tie-breaker on drinker id)
INSERT INTO t4 (c1, c2, c3) VALUES ('d1', 'bar2', 10);
INSERT INTO t4 (c1, c2, c3) VALUES ('d2', 'bar2', 10);

