counterexample:
-- Insert a row into t2 that does not have any matching row in t5
INSERT INTO t2 (c1, c2) VALUES ('A', 'dummy');

-- (Optionally, insert a row into t2 for another key along with a matching t5 row to show that Q2 can return data when available.)

-- Insert an additional t2 row which will be matched by t5
INSERT INTO t2 (c1, c2) VALUES ('B', 'dummy');

-- For t5, we need to satisfy the foreign key: t5.c1 references t1(c1) and t5.c2 references t2(c1).
-- Therefore, we first insert the necessary row into t1 for foreign key support
INSERT INTO t1 (c1, c2) VALUES ('X', 'notused');

-- Now insert a row into t5 with t5.c2 = 'B' so that Q1 and Q2 return a row for key 'B'
INSERT INTO t5 (c1, c2, c3) VALUES ('X', 'B', 10.00);

-- Also, to satisfy the primary key and to have a minimal-price scenario, we add another row for 'B' with a higher price
INSERT INTO t5 (c1, c2, c3) VALUES ('X', 'B', 12.00);

