-- Prepare the minimal required data respecting foreign key constraints

-- t1 is referenced by t5, so insert t1 rows for t5.c1 values
INSERT INTO t1 (c1, c2) VALUES ('X', 'dummy');
INSERT INTO t1 (c1, c2) VALUES ('Y', 'dummy2');

-- Insert a row into t2. (The second column can be any non-null value.)
INSERT INTO t2 (c1, c2) VALUES ('A', 'dummy');

-- Insert two rows into t5 for t2 key 'A' with the same price (the minimal price).
-- Note: t5.c1 serves as an identifier coming from t1, while t5.c2 references t2.
